import { getRelatedProducts } from '@/lib/data'

/**
 * Reads the route's URL data (searchParams) inside the Suspense boundary, then
 * calls the cached lookup keyed on it. Because the cached result depends on
 * URL data, it is excluded from the shared App Shell (the default prefetch)
 * but resolved by a per-link `<Link prefetch>` from the featured-product link.
 */
export async function RelatedProducts({
  searchParams,
}: Pick<PageProps<'/product'>, 'searchParams'>) {
  const { related } = await searchParams
  const view = typeof related === 'string' ? related : ''
  const relatedProducts = await getRelatedProducts(view)

  return (
    <ul>
      {relatedProducts.map((product) => (
        <li key={product}>{product}</li>
      ))}
    </ul>
  )
}

